mapper.select:
SELECT * FROM (
SELECT a.cprc_llave AS llaveTabla, a.cprc_nombre AS nombre, a.cprc_codigo AS codigo, a.cprc_estado AS estado, a.cprc_imagen AS imagen, a.nprc_prioridad AS prioridad, a.cprc_tipo AS tipo, 'P' AS categoria, a.cprc_macroproceso AS nodoSuperior, p2.cprc_nombre AS nodoSuperiorNombre FROM proceso_prcp a LEFT JOIN proceso_prcp p2 ON p2.cprc_llave = a.cprc_macroproceso WHERE a.cprc_estado = 'A' AND ( a.cprc_macroproceso IS NULL OR a.cprc_macroproceso = '' OR a.cprc_macroproceso = a.cprc_llave )
UNION ALL
SELECT a.cwbs_llave AS llaveTabla, a.cwbs_nombre AS nombre, a.cwbs_codigo AS codigo, a.cwbs_estado AS estado, NULL AS imagen, NULL AS prioridad, NULL AS tipo, 'W' AS categoria, a.cwbs_proceso AS nodoSuperior, p2.cprc_nombre AS nodoSuperiorNombre FROM webservice_wbsp a LEFT JOIN proceso_prcp p2 ON p2.cprc_llave = a.cwbs_proceso WHERE a.cwbs_estado = 'A' AND a.cwbs_proceso IS NULL
UNION ALL
SELECT a.cind_llave AS llaveTabla, a.cind_nombre AS nombre, a.cind_codigo AS codigo, a.cind_estado AS estado, a.cind_imagen AS imagen, NULL AS prioridad, NULL AS tipo, 'I' AS categoria, a.cind_proceso AS nodoSuperior, p2.cprc_nombre AS nodoSuperiorNombre FROM account.indicador_ind a LEFT JOIN proceso_prcp p2 ON p2.cprc_llave = a.cind_proceso WHERE a.cind_estado = 'A' AND a.cind_proceso IS NULL
SELECT a.cprc_llave AS llaveTabla, a.cprc_nombre AS nombre, a.cprc_codigo AS codigo, a.cprc_estado AS estado, a.cprc_imagen AS imagen, a.nprc_prioridad AS prioridad, a.cprc_tipo AS tipo, 'P' AS categoria, a.cprc_macroproceso AS nodoSuperior, p2.cprc_nombre AS nodoSuperiorNombre FROM proceso_prcp a LEFT JOIN proceso_prcp p2 ON p2.cprc_llave = a.cprc_macroproceso WHERE a.cprc_estado = 'A' AND a.cprc_macroproceso = #{llavePadre}
UNION ALL
SELECT a.cdpl_llave AS llaveTabla, a.cdpl_nombre AS nombre, a.cdpl_codigo AS codigo, a.cdpl_estado AS estado, a.cdpl_imagen AS imagen, NULL AS prioridad, a.cdpl_tipo AS tipo, 'L' AS categoria, a.cdpl_padre AS nodoSuperior, p2.cdpl_nombre AS nodoSuperiorNombre FROM documentoplantilla_dplp a LEFT JOIN documentoplantilla_dplp p2 ON p2.cdpl_llave = a.cdpl_padre WHERE a.cdpl_estado = 'A' AND a.cdpl_padre = #{llavePadre}
UNION ALL
SELECT a.cwbs_llave AS llaveTabla, a.cwbs_nombre AS nombre, a.cwbs_codigo AS codigo, a.cwbs_estado AS estado, NULL AS imagen, NULL AS prioridad, NULL AS tipo, 'W' AS categoria, a.cwbs_proceso AS nodoSuperior, p2.cprc_nombre AS nodoSuperiorNombre FROM webservice_wbsp a LEFT JOIN proceso_prcp p2 ON p2.cprc_llave = a.cwbs_proceso WHERE a.cwbs_estado = 'A' AND a.cwbs_proceso = #{llavePadre}
UNION ALL
SELECT a.cind_llave AS llaveTabla, a.cind_nombre AS nombre, a.cind_codigo AS codigo, a.cind_estado AS estado, a.cind_imagen AS imagen, NULL AS prioridad, NULL AS tipo, 'I' AS categoria, a.cind_proceso AS nodoSuperior, p2.cprc_nombre AS nodoSuperiorNombre FROM account.indicador_ind a LEFT JOIN proceso_prcp p2 ON p2.cprc_llave = a.cind_proceso WHERE a.cind_estado = 'A' AND a.cind_proceso = #{llavePadre}
SELECT a.cdpc_llave AS llaveTabla, a.cdpc_nombre AS nombre, a.cdpc_codigo AS codigo, a.cdpc_estado AS estado, a.cdpc_imagen AS imagen, a.ndpc_orden AS prioridad, a.cdpc_formato AS tipo, 'C' AS categoria, a.cdpc_plantilla AS nodoSuperior, p2.cdpl_nombre AS nodoSuperiorNombre FROM documentoplantillacaracteristica_dpcp a LEFT JOIN documentoplantilla_dplp p2 ON p2.cdpl_llave = a.cdpc_plantilla WHERE a.cdpc_estado = 'A' AND a.cdpc_plantilla = #{llavePadre}
UNION ALL
SELECT a.crpb_llave AS llaveTabla, a.crpb_nombre AS nombre, a.crpb_codigo AS codigo, a.crpb_estado AS estado, NULL AS imagen, NULL AS prioridad, NULL AS tipo, 'E' AS categoria, a.crpb_plantilla AS nodoSuperior, p2.cdpl_nombre AS nodoSuperiorNombre FROM reportebase_rpbp a LEFT JOIN documentoplantilla_dplp p2 ON p2.cdpl_llave = a.crpb_plantilla WHERE a.crpb_estado = 'A' AND a.crpb_plantilla = #{llavePadre}
UNION ALL
SELECT a.cdpl_llave AS llaveTabla, a.cdpl_nombre AS nombre, a.cdpl_codigo AS codigo, a.cdpl_estado AS estado, a.cdpl_imagen AS imagen, NULL AS prioridad, a.cdpl_tipo AS tipo, 'L' AS categoria, a.cdpl_padre AS nodoSuperior, p2.cdpl_nombre AS nodoSuperiorNombre FROM documentoplantilla_dplp a LEFT JOIN documentoplantilla_dplp p2 ON p2.cdpl_llave = a.cdpl_padre WHERE a.cdpl_estado = 'A' AND a.cdpl_padre = #{llavePadre}
) h ORDER BY prioridad, nombre
